import { readFile, rename, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

import openapiTS, { astToString, type OpenAPI3 } from "openapi-typescript";

import { loadTypesEnv } from "../env.ts";

const OUTPUT_FILE = fileURLToPath(new URL("../src/generated/schema.gen.ts", import.meta.url));
const HEADER =
  "// GENERATED by scripts/generate-types.ts from the server's OpenAPI document.\n// Do not edit by hand, run `pnpm types:generate`.\n\n";

async function fetchSpec(url: URL): Promise<OpenAPI3> {
  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`responded with HTTP ${response.status}`);
  }

  return (await response.json()) as OpenAPI3;
}

async function generate(spec: OpenAPI3): Promise<string> {
  const ast = await openapiTS(spec);

  return HEADER + astToString(ast);
}

async function readCurrent(): Promise<string | undefined> {
  try {
    return await readFile(OUTPUT_FILE, "utf8");
  } catch {
    return undefined;
  }
}

async function main(): Promise<void> {
  const check = process.argv.includes("--check");
  const { openapiUrl } = loadTypesEnv();

  let output: string;

  try {
    output = await generate(await fetchSpec(openapiUrl));
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);

    throw new Error(`Could not generate types from ${openapiUrl.href}: ${reason}`, {
      cause: error,
    });
  }

  if (check) {
    if ((await readCurrent()) !== output) {
      throw new Error("schema.gen.ts is stale, run `pnpm types:generate` and commit the result");
    }

    console.log("schema.gen.ts is up to date");

    return;
  }

  const temporaryFile = `${OUTPUT_FILE}.tmp`;

  await writeFile(temporaryFile, output);
  await rename(temporaryFile, OUTPUT_FILE);

  console.log(`Wrote ${OUTPUT_FILE}`);
}

try {
  await main();
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
}
